import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { fullMatrix } from '../../scripts/lib/affected-matrix.mjs';
import { HEAVY_TESTS, STATISTICAL_TESTS } from '../../scripts/lib/test-scope.mjs';

// The named heavy shards: every test file that ran over 60 s inside a numbered shard has a CI job of its own, so no shard
// runs over 4 minutes on a quiet runner (docs/designs/agent-workflow.md, CI wall time). Adding a file here is a
// decision. The matrix is generated by scripts/lib/affected-matrix.mjs from HEAVY_TESTS and STATISTICAL_TESTS, so the
// job ids below are what a full run shows in the checks list.
const PINNED = {
    'heavy-train-pool': 'test/train-pool.slow.test.js',
    'heavy-scripted-temperature': 'test/evo/scripted-temperature.slow.test.js',
    'heavy-train': 'test/train.slow.test.js',
    'heavy-gate-validity': 'test/evo/gate-validity.slow.test.js',
    'heavy-bench': 'test/bench.slow.test.js',
};

describe('the full test matrix', () => {
    const jobs = fullMatrix();

    it('names each heavy job and its file, and no other', () => {
        const heavy = Object.fromEntries(jobs.filter((job) => job.pass === 'heavy').map((job) => [job.id, job.files]));
        expect(heavy).toEqual(PINNED);
        expect([...HEAVY_TESTS].sort()).toEqual(Object.values(PINNED).sort());
    });

    it('names each statistical job and its file, one job per file', () => {
        const statistical = jobs.filter((job) => job.pass === 'statistical');
        expect(statistical.map((job) => job.files)).toEqual(STATISTICAL_TESTS);
        expect(statistical.map((job) => job.id)).toEqual([
            'statistical-deliberate-controllers',
            'statistical-survivable-world',
            'statistical-anti-exploit',
            'statistical-practice',
            'statistical-metric-invariants',
        ]);
    });

    it('keeps the eight numbered shards', () => {
        const shards = jobs.filter((job) => job.pass === 'shard');
        expect(shards.map((job) => `${job.id}:${job.shard}`)).toEqual(
            Array.from({ length: 8 }, (_, i) => `shard-${i + 1}:${i + 1}/8`),
        );
    });

    it('is the matrix check.yml runs, not a list kept in the workflow', () => {
        const check = readFileSync('.github/workflows/check.yml', 'utf8');
        expect(check).toContain('matrix: ${{ fromJSON(needs.scope.outputs.matrix) }}');
        expect(check).not.toMatch(/pass: (shard|heavy|statistical), id:/);
    });
});
